CREATE DATABASE IF NOT EXISTS restro;
USE restro;
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE job_types(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE employees(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(20),
 role_id INT,department_id INT,job_type_id INT,designation VARCHAR(80),active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(job_type_id) REFERENCES job_types(id));
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),phone VARCHAR(20) UNIQUE,address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,parent_id INT NULL,FOREIGN KEY(parent_id) REFERENCES categories(id));
CREATE TABLE items(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category_id INT,base_price DECIMAL(10,2) NOT NULL,is_veg TINYINT DEFAULT 1,available TINYINT DEFAULT 1,description TEXT,image_prompt TEXT,image_url VARCHAR(2048),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE item_variations(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,name VARCHAR(60) NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE);
CREATE TABLE item_skus(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,sku VARCHAR(40) UNIQUE,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE);
CREATE TABLE item_addons(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,name VARCHAR(60) NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE);
CREATE TABLE table_places(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL);
CREATE TABLE tables(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL,place_id INT,capacity INT DEFAULT 4,status ENUM('free','occupied') DEFAULT 'free',FOREIGN KEY(place_id) REFERENCES table_places(id));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,order_type ENUM('dine_in','pickup','delivery') NOT NULL,table_id INT NULL,customer_id INT NULL,employee_id INT,
 status ENUM('placed','preparing','ready','served','delivered','cancelled') DEFAULT 'placed',payment_status ENUM('unpaid','paid') DEFAULT 'unpaid',
 subtotal DECIMAL(10,2) DEFAULT 0,tax DECIMAL(10,2) DEFAULT 0,discount DECIMAL(10,2) NOT NULL DEFAULT 0,round_off DECIMAL(10,2) NOT NULL DEFAULT 0,total DECIMAL(10,2) DEFAULT 0,notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(table_id) REFERENCES tables(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,item_id INT NOT NULL,item_name VARCHAR(120),qty INT NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE order_variations(id INT AUTO_INCREMENT PRIMARY KEY,order_item_id INT NOT NULL,variation_id INT,name VARCHAR(60),price DECIMAL(10,2),FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE CASCADE);
CREATE TABLE order_addons(id INT AUTO_INCREMENT PRIMARY KEY,order_item_id INT NOT NULL,addon_id INT,name VARCHAR(60),price DECIMAL(10,2),FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE CASCADE);
CREATE TABLE checkout(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,amount DECIMAL(10,2),method ENUM('cash','card','upi'),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE transactions(id INT AUTO_INCREMENT PRIMARY KEY,checkout_id INT NOT NULL,reference VARCHAR(60),status ENUM('success','failed') DEFAULT 'success',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(checkout_id) REFERENCES checkout(id));
CREATE TABLE settings(id INT AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(60) UNIQUE,setting_value VARCHAR(255));
CREATE TABLE lookups(id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(40),value VARCHAR(80));
